  3264  // Calculate number of index levels given min_shift and the header contig
  3265  // list.  Also returns number of contigs in *nids_out.
  3266  static int idx_calc_n_lvls_ids(const bcf_hdr_t *h, int min_shift,
  3267                                 int starting_n_lvls, int *nids_out)
  3268  {
  3269      int n_lvls, i, nids = 0;
  3270      int64_t max_len = 0, s;
  3271
  3272      for (i = 0; i < h->n[BCF_DT_CTG]; ++i)
  3273      {
  3274          if ( !h->id[BCF_DT_CTG][i].val ) continue;
  3275          if ( max_len < h->id[BCF_DT_CTG][i].val->info[0] )
  3276              max_len = h->id[BCF_DT_CTG][i].val->info[0];
  3277          nids++;
  3278      }
  3279      if ( !max_len ) max_len = (1LL<<31) - 1;  // In case contig line is broken.
  3280      max_len += 256;
  3281      s = 1LL << (min_shift + starting_n_lvls * 3);
  3282      for (n_lvls = starting_n_lvls; max_len > s; ++n_lvls, s <<= 3);
  3283
  3284      if (nids_out) *nids_out = nids;
  3285      return n_lvls;
  3286  }
