  3288  hts_idx_t *bcf_index(htsFile *fp, int min_shift)
  3289  {
  3290      int n_lvls;
  3291      bcf1_t *b = NULL;
  3292      hts_idx_t *idx = NULL;
  3293      bcf_hdr_t *h;
  3294      int r;
  3295      h = bcf_hdr_read(fp);
  3296      if ( !h ) return NULL;
  3297      int nids = 0;
  3298      n_lvls = idx_calc_n_lvls_ids(h, min_shift, 0, &nids);
  3299      idx = hts_idx_init(nids, HTS_FMT_CSI, bgzf_tell(fp->fp.bgzf), min_shift, n_lvls);
  3300      if (!idx) goto fail;
  3301      b = bcf_init1();
  3302      if (!b) goto fail;
  3303      while ((r = bcf_read1(fp,h, b)) >= 0) {
  3304          int ret;
  3305          ret = hts_idx_push(idx, b->rid, b->pos, b->pos + b->rlen, bgzf_tell(fp->fp.bgzf), 1);
  3306          if (ret < 0) goto fail;
  3307      }
  3308      if (r < -1) goto fail;
  3309      hts_idx_finish(idx, bgzf_tell(fp->fp.bgzf));
  3310      bcf_destroy1(b);
  3311      bcf_hdr_destroy(h);
  3312      return idx;
  3313
  3314   fail:
  3315      hts_idx_destroy(idx);
  3316      bcf_destroy1(b);
  3317      bcf_hdr_destroy(h);
  3318      return NULL;
  3319  }
