  3337      if ((fp = hts_open(fn, "rb")) == 0) return -2;
  3338      if (n_threads)
  3339          hts_set_threads(fp, n_threads);
  3340      if ( fp->format.compression!=bgzf ) { hts_close(fp); return -3; }
  3341      switch (fp->format.format) {
  3342          case bcf:
  3343              if (!min_shift) {
