  3353                  else ret = -1;
  3354              }
  3355              break;
  3356
  3357          case vcf:
  3358              tbx = tbx_index(hts_get_bgzfp(fp), min_shift, &tbx_conf_vcf);
  3359              if (tbx) {
  3360                  ret = hts_idx_save_as(tbx->idx, fn, fnidx, min_shift > 0 ? HTS_FMT_CSI : HTS_FMT_TBI);
