  3362                  tbx_destroy(tbx);
  3363              }
  3364              else ret = -1;
  3365              break;
  3366
  3367          default:
  3368              ret = -3;
  3369              break;
  3370      }
  3371      hts_close(fp);
  3372      return ret;
  3373  }
