  3424  // Initialise fp->idx for the current format type.
  3425  // This must be called after the header has been written but no other data.
  3426  int bcf_idx_init(htsFile *fp, bcf_hdr_t *h, int min_shift, const char *fnidx) {
  3427      int n_lvls, nids = 0;
  3428
  3429      if (fp->format.format == vcf)
  3430          return vcf_idx_init(fp, h, min_shift, fnidx);
  3431
  3432      if (!min_shift)
  3433          min_shift = 14;
  3434
  3435      n_lvls = idx_calc_n_lvls_ids(h, min_shift, 0, &nids);
  3436
  3437      fp->idx = hts_idx_init(nids, HTS_FMT_CSI, bgzf_tell(fp->fp.bgzf), min_shift, n_lvls);
  3438      if (!fp->idx) return -1;
  3439      fp->fnidx = fnidx;
  3440
  3441      return 0;
  3442  }
